    // Constructor to initialize the cat's color
    public Cat(String color) {
        this.color = color;
    }

    @Override
    public void makeSound() {
        System.out.println("Meow!");
    }

    @Override
    public String getName() {
        return "Cat";
    }
}

public class Main {
